    epochWithdrawn[currentEpoch()] += reward;
    require(
        epochWithdrawn[currentEpoch()] <= EPOCH_WITHDRAW_LIMIT,
        "Epoch withdraw limit exceeded"
    );

    // ✅ [Fix 4] Emergency pause
    require(!paused, "Contract paused");

